import numpy as np, math
atoms=[]; xyz=[]
def add(el,r):
    atoms.append(el); xyz.append(np.array(r,dtype=float)); return len(atoms)-1
def unit(v): return np.array(v,dtype=float)/np.linalg.norm(v)
def basis(u):
    # stable transverse pair
    a=np.array([0.,0.,1.]) if abs(u[2])<0.85 else np.array([1.,0.,0.])
    e1=unit(np.cross(u,a)); e2=unit(np.cross(u,e1))
    return e1,e2
def outer_dirs(u):
    e1,e2=basis(u)
    return [unit((1/3)*u + math.sqrt(8/9)*(math.cos(t)*e1+math.sin(t)*e2)) for t in (0,2*math.pi/3,4*math.pi/3)]
def add_methyl(p, cdir, phase=0):
    c=add('C', np.array(p)+1.84*cdir)
    v=unit(np.array(p)-xyz[c]) # C -> P
    e1,e2=basis(v)
    for k in range(3):
        t=phase+2*math.pi*k/3
        hd=unit((-1/3)*v+math.sqrt(8/9)*(math.cos(t)*e1+math.sin(t)*e2))
        add('H',xyz[c]+1.09*hd)
# Ni origin
add('Ni',[0,0,0])
# five-coord trigonal bipyramidal: two axial Si, three equatorial P
ligands=[]
for u in [np.array([0.,0.,1.]),np.array([0.,0.,-1.])]:
    u=unit(u); si=add('Si',2.35*u); ligands.append(('Si',si,u))
for deg in [180,60,300]:
    t=math.radians(deg); u=np.array([math.cos(t),math.sin(t),0.])
    p=add('P',2.22*u); ligands.append(('P',p,u))
# add substituents
for typ,idx,u in ligands:
    if typ=='Si':
        for d in outer_dirs(u): add('F',xyz[idx]+1.60*d)
    else:
        for j,d in enumerate(outer_dirs(u)): add_methyl(xyz[idx],d,phase=j*0.13)
with open('answer.xyz','w') as f:
    f.write(f'{len(atoms)}\nNi(SiF3)2(PMe3)3; trigonal-bipyramidal starting structure\n')
    for e,r in zip(atoms,xyz): f.write(f'{e:2s} {r[0]: .8f} {r[1]: .8f} {r[2]: .8f}\n')
print('atom count',len(atoms))
